import "./VenusInteractorInitializableV2.sol";
import "../interface/IVault.sol";
import "../upgradability/BaseUpgradeableStrategy.sol";

import "../interface/pancakeswap/IPancakeRouter02.sol";

contract VenusFoldStrategyV2 is BaseUpgradeableStrategy, VenusInteractorInitializableV2 {

  using SafeMath for uint256;
  using SafeBEP20 for IBEP20;

  event ProfitNotClaimed();
  event TooLowBalance();

  address constant public pancakeswapRouterV2 = address(0x05fF2B0DB69458A0750badebc4f9e13aDd608C7F);
  bool public allowEmergencyLiquidityShortage = false;
  uint256 public borrowMinThreshold = 0;

  // additional storage slots (on top of BaseUpgradeableStrategy ones) are defined here
  bytes32 internal constant _COLLATERALFACTORNUMERATOR_SLOT = 0x129eccdfbcf3761d8e2f66393221fa8277b7623ad13ed7693a0025435931c64a;
  bytes32 internal constant _COLLATERALFACTORDENOMINATOR_SLOT = 0x606ec222bff56fc4394b829203993803e413c3116299fce7ba56d1e18ce68869;
  bytes32 internal constant _FOLDS_SLOT = 0xa62de150ef612c15565245b7898c849ef17c729d612c5cc6670d42dca253681b;
  bytes32 internal constant _ALLOWED_FEE_NUMERATOR_SLOT = 0x4b6c6fa4369b03464dd976a7e6a631fb74f9eb091c5e8306254025c2e07dc416;

  uint256 public suppliedInUnderlying;
  uint256 public borrowedInUnderlying;
  address[] public liquidationPath;

  event Liquidated(
    uint256 amount
  );

  constructor() public BaseUpgradeableStrategy() {
    assert(_COLLATERALFACTORNUMERATOR_SLOT == bytes32(uint256(keccak256("eip1967.strategyStorage.collateralFactorNumerator")) - 1));
    assert(_COLLATERALFACTORDENOMINATOR_SLOT == bytes32(uint256(keccak256("eip1967.strategyStorage.collateralFactorDenominator")) - 1));
    assert(_FOLDS_SLOT == bytes32(uint256(keccak256("eip1967.strategyStorage.folds")) - 1));
    assert(_ALLOWED_FEE_NUMERATOR_SLOT == bytes32(uint256(keccak256("eip1967.strategyStorage.allowedFeeNumerator")) - 1));
  }

  function initializeStrategy(
    address _storage,
    address _underlying,
    address _vtoken,
    address _vault,
    address _comptroller,
    address _xvs,
    uint256 _collateralFactorNumerator,
    uint256 _collateralFactorDenominator,
    uint256 _folds
  )
  public initializer {
    BaseUpgradeableStrategy.initialize(
      _storage,
      _underlying,
      _vault,
      _comptroller,
      _xvs,
      80, // profit sharing numerator
      1000, // profit sharing denominator
      true, // sell
      1e16, // sell floor
      12 hours // implementation change delay
    );

    VenusInteractorInitializableV2.initialize(_underlying, _vtoken, _comptroller);

    require(IVault(_vault).underlying() == _underlying, "vault does not support underlying");
    _setCollateralFactorDenominator(_collateralFactorDenominator);
    _setCollateralFactorNumerator(_collateralFactorNumerator);
    _setFolds(_folds);
    _setAllowedFeeNumerator(9999);
  }

  modifier updateSupplyInTheEnd() {
    _;
    suppliedInUnderlying = CompleteVToken(vToken()).balanceOfUnderlying(address(this));
    borrowedInUnderlying = CompleteVToken(vToken()).borrowBalanceCurrent(address(this));
  }

  function depositArbCheck() public pure returns (bool) {
    // there's no arb here.
    return true;
  }

  function unsalvagableTokens(address token) public view returns (bool) {
    return (token == rewardToken() || token == underlying() || token == vToken());
  }

  /**
  * The strategy invests by supplying the underlying as a collateral.
  */
  function investAllUnderlying() public restricted updateSupplyInTheEnd {
    uint256 balance = IBEP20(underlying()).balanceOf(address(this));
    // Check before supplying
    uint256 supplied = CompleteVToken(vToken()).balanceOfUnderlying(address(this));
    uint256 borrowed = CompleteVToken(vToken()).borrowBalanceCurrent(address(this));
    if (balance > 0) {
      _supply(balance);
    }
    if (supplied.mul(collateralFactorNumerator()) > borrowed.mul(collateralFactorDenominator()) || supplied == 0) {
      for (uint256 i = 0; i < folds(); i++) {
        uint256 borrowAmount = balance.mul(collateralFactorNumerator()).div(collateralFactorDenominator());
        _borrow(borrowAmount);
        balance = IBEP20(underlying()).balanceOf(address(this));
        if (balance > 0) {
          _supply(balance);
        }
      }
    }
  }

  /**
  * Exits Venus and transfers everything to the vault.
  */
  function withdrawAllToVault() external restricted updateSupplyInTheEnd {
    if (allowEmergencyLiquidityShortage) {
      withdrawMaximum();
    } else {
      withdrawAllWeInvested();
    }
    if (IBEP20(underlying()).balanceOf(address(this)) > 0) {
      IBEP20(underlying()).safeTransfer(vault(), IBEP20(underlying()).balanceOf(address(this)));
    }
  }

  function emergencyExit() external onlyGovernance updateSupplyInTheEnd {
    withdrawMaximum();
  }

  function withdrawMaximum() internal updateSupplyInTheEnd {
    if (sell()) {
      liquidateVenus();
    } else {
      emit ProfitNotClaimed();
    }
    redeemMaximum();
  }

  function withdrawAllWeInvested() internal updateSupplyInTheEnd {
    if (sell()) {
      liquidateVenus();
    } else {
      emit ProfitNotClaimed();
    }
    uint256 _currentSuppliedBalance = CompleteVToken(vToken()).balanceOfUnderlying(address(this));
    uint256 _currentBorrowedBalance = CompleteVToken(vToken()).borrowBalanceCurrent(address(this));

    mustRedeemPartial(_currentSuppliedBalance.sub(_currentBorrowedBalance));
  }

  function withdrawToVault(uint256 amountUnderlying) external restricted updateSupplyInTheEnd {
    uint256 balance = IBEP20(underlying()).balanceOf(address(this));
    if (amountUnderlying <= balance) {
      IBEP20(underlying()).safeTransfer(vault(), amountUnderlying);
      return;
    }

    uint256 toRedeem = amountUnderlying.sub(balance);
    // get some of the underlying
    mustRedeemPartial(toRedeem);

    // transfer the amount requested (or the amount we have) back to vault()
    balance = IBEP20(underlying()).balanceOf(address(this));
    IBEP20(underlying()).safeTransfer(vault(), MathUpgradeable.min(amountUnderlying, balance));

    balance = IBEP20(underlying()).balanceOf(address(this));
    if (balance >0) {
      // invest back to Venus
      investAllUnderlying();
    }
  }

  /**
  * Withdraws all assets, liquidates XVS, and invests again in the required ratio.
  */
  function doHardWork() public restricted {
    if (sell()) {
      liquidateVenus();
    } else {
      emit ProfitNotClaimed();
    }
    investAllUnderlying();
  }

  /**
  * Redeems maximum that can be redeemed from Venus.
  * Redeem the minimum of the underlying we own, and the underlying that the vToken can
  * immediately retrieve. Ensures that `redeemMaximum` doesn't fail silently.
  *
  * DOES NOT ensure that the strategy vUnderlying balance becomes 0.
  */
  function redeemMaximum() internal {
    if (folds()>0) {
      redeemMaximumWithLoan(
        collateralFactorNumerator(),
        collateralFactorDenominator(),
        borrowMinThreshold
      );
    } else {
      redeemMaximumNoFold();
    }
  }

  /**
  * Redeems `amountUnderlying` or fails.
  */
  function mustRedeemPartial(uint256 amountUnderlyingToRedeem) internal {
    uint256 initialBalance = IBEP20(underlying()).balanceOf(address(this));
    require(
      CompleteVToken(vToken()).getCash() >= amountUnderlyingToRedeem,
      "market cash cannot cover liquidity"
    );
    if (folds() > 0) {
      redeemMaximum();
    } else {
      _redeemUnderlying(amountUnderlyingToRedeem);
    }
    uint256 finalBalance = IBEP20(underlying()).balanceOf(address(this));
    require(
      finalBalance.sub(initialBalance) >= amountUnderlyingToRedeem.mul(allowedFeeNumerator()).div(10000),
      "Unable to withdraw the entire amountUnderlyingToRedeem");
  }

  /**
  * Salvages a token.
  */
  function salvage(address recipient, address token, uint256 amount) public onlyGovernance {
    // To make sure that governance cannot come in and take away the coins
    require(!unsalvagableTokens(token), "token is defined as not salvagable");
    IBEP20(token).safeTransfer(recipient, amount);
  }

  function liquidateVenus() internal {
    // Calculating rewardBalance is needed for the case underlying = reward token
    uint256 balance = IBEP20(rewardToken()).balanceOf(address(this));
    claimVenus();
    uint256 balanceAfter = IBEP20(rewardToken()).balanceOf(address(this));
    uint256 rewardBalance = balanceAfter.sub(balance);

    if (rewardBalance < sellFloor() || rewardBalance == 0) {
      emit TooLowBalance();
      return;
    }

    // give a profit share to fee forwarder, which re-distributes this to
    // the profit sharing pools
    notifyProfitInRewardToken(rewardBalance);

    balance = IBEP20(rewardToken()).balanceOf(address(this));

    emit Liquidated(balance);

    // no liquidation needed when underlying is reward token
    if (underlying() == rewardToken()) {
      return;
    }

    // we can accept 1 as minimum as this will be called by trusted roles only
    uint256 amountOutMin = 1;
    IBEP20(rewardToken()).safeApprove(address(pancakeswapRouterV2), 0);
    IBEP20(rewardToken()).safeApprove(address(pancakeswapRouterV2), balance);

    IPancakeRouter02(pancakeswapRouterV2).swapExactTokensForTokens(
      balance,
      amountOutMin,
      liquidationPath,
      address(this),
      block.timestamp
    );
  }

  /**
  * Returns the current balance. Ignores XVS that was not liquidated and invested.
  */
  function investedUnderlyingBalance() public view returns (uint256) {
    // underlying in this strategy + underlying redeemable from Venus + loan
    return IBEP20(underlying()).balanceOf(address(this))
    .add(suppliedInUnderlying)
    .sub(borrowedInUnderlying);
  }

  function setAllowLiquidityShortage(bool allowed) external restricted {
    allowEmergencyLiquidityShortage = allowed;
  }

  function setBorrowMinThreshold(uint256 threshold) public onlyGovernance {
    borrowMinThreshold = threshold;
  }

  // updating collateral factor
  // note 1: one should settle the loan first before calling this
  // note 2: collateralFactorDenominator is 1000, therefore, for 20%, you need 200
  function _setCollateralFactorNumerator(uint256 _numerator) internal {
    require(_numerator < uint(600).mul(collateralFactorDenominator()).div(1000), "Collateral factor cannot be this high");
    setUint256(_COLLATERALFACTORNUMERATOR_SLOT, _numerator);
  }

  function collateralFactorNumerator() public view returns (uint256) {
    return getUint256(_COLLATERALFACTORNUMERATOR_SLOT);
  }

  function _setCollateralFactorDenominator(uint256 _denominator) internal {
    setUint256(_COLLATERALFACTORDENOMINATOR_SLOT, _denominator);
  }

  function collateralFactorDenominator() public view returns (uint256) {
    return getUint256(_COLLATERALFACTORDENOMINATOR_SLOT);
  }

  function _setFolds(uint256 _folds) public onlyGovernance {
    setUint256(_FOLDS_SLOT, _folds);
  }

  function folds() public view returns (uint256) {
    return getUint256(_FOLDS_SLOT);
  }

  function allowedFeeNumerator() public view returns (uint256) {
    return getUint256(_ALLOWED_FEE_NUMERATOR_SLOT);
  }

  function setSellFloor(uint256 floor) public onlyGovernance {
    _setSellFloor(floor);
  }

  function _setAllowedFeeNumerator(uint256 numerator) public onlyGovernance {
    setUint256(_ALLOWED_FEE_NUMERATOR_SLOT, numerator);
  }

  function setSell(bool s) public onlyGovernance {
    _setSell(s);
  }

  function finalizeUpgrade() external onlyGovernance updateSupplyInTheEnd {
    _finalizeUpgrade();
  }
}

contracts/base/venus-base/VenusInteracto.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.6.12;

import "@pancakeswap/pancake-swap-lib/contracts/token/BEP20/IBEP20.sol";
import "@pancakeswap/pancake-swap-lib/contracts/token/BEP20/SafeBEP20.sol";

import "@openzeppelin/contracts-upgradeable/math/MathUpgradeable.sol";
import "@pancakeswap/pancake-swap-lib/contracts/math/SafeMath.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "./interface/IVBNB.sol";
import "./interface/CompleteVToken.sol";
import "./wbnb/WBNB.sol";
import "@openzeppelin/contracts-upgradeable/proxy/Initializable.sol";

contract VenusInteractorInitializableV2 is Initializable, ReentrancyGuardUpgradeable {

  using SafeMath for uint256;
  using SafeBEP20 for IBEP20;

  address public constant _wbnb = address(0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c);

  bytes32 internal constant _INTERACTOR_UNDERLYING_SLOT = 0x3e9f9f7ea72bae20746fd93eefa9f38d4f124c4ea7b6f6d6641f8cca268c5697;
  bytes32 internal constant _VTOKEN_SLOT = 0xd10d7aea8cd8c74e560aafdc0a5d3820e89ad384815628d13908d84a477ec585;
  bytes32 internal constant _COMPTROLLER_SLOT = 0xd6eb26dcc0c659c2dac09757ba602511aadae03cd65090aa8c177fb971879dd6;

  constructor() public {
    assert(_INTERACTOR_UNDERLYING_SLOT == bytes32(uint256(keccak256("eip1967.interactorStorage.underlying")) - 1));
    assert(_VTOKEN_SLOT == bytes32(uint256(keccak256("eip1967.interactorStorage.vtoken")) - 1));
    assert(_COMPTROLLER_SLOT == bytes32(uint256(keccak256("eip1967.interactorStorage.comptroller")) - 1));
  }

  function initialize(
    address _underlying,
    address _vtoken,
    address _comptroller
  ) public initializer {
    __ReentrancyGuard_init();
    // Comptroller:
    _setComptroller(_comptroller);
    _setInteractorUnderlying(_underlying);
    _setVToken(_vtoken);

    // Enter the market
    address[] memory vTokens = new address[](1);
    vTokens[0] = _vtoken;
    ComptrollerInterface(comptroller()).enterMarkets(vTokens);

  }

  /**
  * Supplies BNB to Venus
  * Unwraps WBNB to BNB, then invoke the special mint for vBNB
  * We ask to supply "amount", if the "amount" we asked to supply is
  * more than balance (what we really have), then only supply balance.
  * If we the "amount" we want to supply is less than balance, then
  * only supply that amount.
  */
  function _supplyBNBInWBNB(uint256 amountInWBNB) internal nonReentrant {
    // underlying here is WBNB
    uint256 balance = IBEP20(_underlying()).balanceOf(address(this)); // supply at most "balance"
    if (amountInWBNB < balance) {
      balance = amountInWBNB; // only supply the "amount" if its less than what we have
    }
    WBNB wbnb = WBNB(payable(_wbnb));
    wbnb.withdraw(balance); // Unwrapping
    IVBNB(vToken()).mint{value: balance}();
  }

  /**
  * Redeems BNB from Venus
  * receives BNB. Wrap all the BNB that is in this contract.
  */
  function _redeemBNBInvTokens(uint256 amountVTokens) internal nonReentrant {
    _redeemInVTokens(amountVTokens);
    WBNB wbnb = WBNB(payable(_wbnb));
    wbnb.deposit{value: address(this).balance}();
  }

  /**
  * Supplies to Venus
  */
  function _supply(uint256 amount) internal returns(uint256) {
    uint256 balance = IBEP20(_underlying()).balanceOf(address(this));
    if (amount < balance) {
      balance = amount;
    }
    IBEP20(_underlying()).safeApprove(vToken(), 0);
    IBEP20(_underlying()).safeApprove(vToken(), balance);
    uint256 mintResult = CompleteVToken(vToken()).mint(balance);
    require(mintResult == 0, "Supplying failed");
    return balance;
  }

  /**
  * Borrows against the collateral
  */
  function _borrow(uint256 amountUnderlying) internal {
    // Borrow, check the balance for this contract's address
    uint256 result = CompleteVToken(vToken()).borrow(amountUnderlying);
    require(result == 0, "Borrow failed");
  }

  /**
  * Borrows against the collateral
  */
  function _borrowInWBNB(uint256 amountUnderlying) internal {
    // Borrow BNB, wraps into WBNB
    uint256 result = CompleteVToken(vToken()).borrow(amountUnderlying);
    require(result == 0, "Borrow failed");
    WBNB wbnb = WBNB(payable(_wbnb));
    wbnb.deposit{value: address(this).balance}();
  }

  /**
  * Repays a loan
  */
  function _repay(uint256 amountUnderlying) internal {
    IBEP20(_underlying()).safeApprove(vToken(), 0);
    IBEP20(_underlying()).safeApprove(vToken(), amountUnderlying);
    CompleteVToken(vToken()).repayBorrow(amountUnderlying);
    IBEP20(_underlying()).safeApprove(vToken(), 0);
  }

  /**
  * Repays a loan in BNB
  */
  function _repayInWBNB(uint256 amountUnderlying) internal {
    WBNB wbnb = WBNB(payable(_wbnb));
    wbnb.withdraw(amountUnderlying); // Unwrapping
    IVBNB(vToken()).repayBorrow{value: amountUnderlying}();
  }

  /**
  * Redeem liquidity in vTokens
  */
  function _redeemInVTokens(uint256 amountVTokens) internal {
    if(amountVTokens > 0){
      CompleteVToken(vToken()).redeem(amountVTokens);
    }
  }

  /**
  * Redeem liquidity in underlying
  */
  function _redeemUnderlying(uint256 amountUnderlying) internal {
    if (amountUnderlying > 0) {
      CompleteVToken(vToken()).redeemUnderlying(amountUnderlying);
    }
  }

  /**
  * Redeem liquidity in underlying
  */
  function redeemUnderlyingInWBNB(uint256 amountUnderlying) internal {
    if (amountUnderlying > 0) {
      _redeemUnderlying(amountUnderlying);
      WBNB wbnb = WBNB(payable(_wbnb));
      wbnb.deposit{value: address(this).balance}();
    }
  }

  /**
  * Get XVS
  */
  function claimVenus() public {
    address[] memory markets = new address[](1);
    markets[0] = address(vToken());
    ComptrollerInterface(comptroller()).claimVenus(address(this), markets);
  }

  function redeemMaximumWithLoan(uint256 collateralFactorNumerator, uint256 collateralFactorDenominator, uint256 borrowMinThreshold) internal {
    // amount of liquidity in Venus
    uint256 available = CompleteVToken(vToken()).getCash();
    // amount we supplied
    uint256 supplied = CompleteVToken(vToken()).balanceOfUnderlying(address(this));
    // amount we borrowed
    uint256 borrowed = CompleteVToken(vToken()).borrowBalanceCurrent(address(this));

    while (borrowed > borrowMinThreshold) {
      uint256 requiredCollateral = borrowed
        .mul(collateralFactorDenominator)
        .add(collateralFactorNumerator.div(2))
        .div(collateralFactorNumerator);

      // redeem just as much as needed to repay the loan
      uint256 wantToRedeem = supplied.sub(requiredCollateral);
      _redeemUnderlying(MathUpgradeable.min(wantToRedeem, available));

      // now we can repay our borrowed amount
      uint256 balance = IBEP20(_underlying()).balanceOf(address(this));
      _repay(MathUpgradeable.min(borrowed, balance));

      // update the parameters
      available = CompleteVToken(vToken()).getCash();
      borrowed = CompleteVToken(vToken()).borrowBalanceCurrent(address(this));
      supplied = CompleteVToken(vToken()).balanceOfUnderlying(address(this));
    }

    // redeem the most we can redeem
    _redeemUnderlying(MathUpgradeable.min(available, supplied));
  }

  function redeemMaximumNoFold() internal {
    // amount of liquidity in Venus
    uint256 available = CompleteVToken(vToken()).getCash();
    // amount we supplied
    uint256 supplied = CompleteVToken(vToken()).balanceOfUnderlying(address(this));

    _redeemUnderlying(MathUpgradeable.min(supplied, available));
  }

  function redeemMaximumWBNBWithLoan(uint256 collateralFactorNumerator, uint256 collateralFactorDenominator, uint256 borrowMinThreshold) internal {
    // amount of liquidity in Venus
    uint256 available = CompleteVToken(vToken()).getCash();
    // amount of WBNB we supplied
    uint256 supplied = CompleteVToken(vToken()).balanceOfUnderlying(address(this));
    // amount of WBNB we borrowed
    uint256 borrowed = CompleteVToken(vToken()).borrowBalanceCurrent(address(this));

    while (borrowed > borrowMinThreshold) {
      uint256 requiredCollateral = borrowed
        .mul(collateralFactorDenominator)
        .add(collateralFactorNumerator.div(2))
        .div(collateralFactorNumerator);

      // redeem just as much as needed to repay the loan
      uint256 wantToRedeem = supplied.sub(requiredCollateral);
      redeemUnderlyingInWBNB(MathUpgradeable.min(wantToRedeem, available));

      // now we can repay our borrowed amount
      uint256 balance = IBEP20(_underlying()).balanceOf(address(this));
      _repayInWBNB(MathUpgradeable.min(borrowed, balance));

      // update the parameters
      available = CompleteVToken(vToken()).getCash();
      borrowed = CompleteVToken(vToken()).borrowBalanceCurrent(address(this));
      supplied = CompleteVToken(vToken()).balanceOfUnderlying(address(this));
    }

    // redeem the most we can redeem
    redeemUnderlyingInWBNB(MathUpgradeable.min(available, supplied));
  }

  function redeemMaximumWBNBNoFold() internal {
    // amount of liquidity in Venus
    uint256 available = CompleteVToken(vToken()).getCash();
    // amount we supplied
    uint256 supplied = CompleteVToken(vToken()).balanceOfUnderlying(address(this));

    redeemUnderlyingInWBNB(MathUpgradeable.min(supplied, available));
  }

  function getLiquidity() external view returns(uint256) {
    return CompleteVToken(vToken()).getCash();
  }

  function redeemMaximumToken() internal {
    // amount of tokens in vtoken
    uint256 available = CompleteVToken(vToken()).getCash();
    // amount of tokens we own
    uint256 owned = CompleteVToken(vToken()).balanceOfUnderlying(address(this));

    // redeem the most we can redeem
    _redeemUnderlying(available < owned ? available : owned);
  }

  receive() external payable {} // this is needed for the WBNB unwrapping

  function _setInteractorUnderlying(address _address) internal {
    _setAddress(_INTERACTOR_UNDERLYING_SLOT, _address);
  }

  function _underlying() internal virtual view returns (address) {
    return _getAddress(_INTERACTOR_UNDERLYING_SLOT);
  }

  function _setVToken(address _address) internal {
    _setAddress(_VTOKEN_SLOT, _address);
  }

  function vToken() public virtual view returns (address) {
    return _getAddress(_VTOKEN_SLOT);
  }

  function _setComptroller(address _address) internal {
    _setAddress(_COMPTROLLER_SLOT, _address);
  }

  function comptroller() public virtual view returns (address) {
    return _getAddress(_COMPTROLLER_SLOT);
  }

  function _setAddress(bytes32 slot, address _address) internal {
    // solhint-disable-next-line no-inline-assembly
    assembly {
      sstore(slot, _address)
    }
  }

  function _getAddress(bytes32 slot) internal view returns (address str) {
    // solhint-disable-next-line no-inline-assembly
    assembly {
      str := sload(slot)
    }
  }
}

contracts/base/venus-base/interface/Comp.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.6.12;

import "./VTokenInterfaces.sol";

abstract contract CompleteVToken is VBep20Interface, VTokenInterface {}

// SPDX-License-Identifier: MIT

pragma solidity ^0.6.12;

abstract contract ComptrollerInterface {
    // implemented, but missing from the interface
    function getAccountLiquidity(address account) external virtual view returns (uint, uint, uint);
    function getHypotheticalAccountLiquidity(
        address account,
        address cTokenModify,
        uint redeemTokens,
        uint borrowAmount) external virtual view returns (uint, uint, uint);
    function claimVenus(address holder, address[] memory vTokens) external virtual;

    /// @notice Indicator that this is a Comptroller contract (for inspection)
    bool public constant isComptroller = true;

    /*** Assets You Are In ***/

    function enterMarkets(address[] calldata vTokens) external virtual returns (uint[] memory);
    function exitMarket(address vToken) external virtual returns (uint);

    /*** Policy Hooks ***/

    function mintAllowed(address vToken, address minter, uint mintAmount) external virtual returns (uint);
    function mintVerify(address vToken, address minter, uint mintAmount, uint mintTokens) external virtual;

    function redeemAllowed(address vToken, address redeemer, uint redeemTokens) external virtual returns (uint);
    function redeemVerify(address vToken, address redeemer, uint redeemAmount, uint redeemTokens) external virtual;

    function borrowAllowed(address vToken, address borrower, uint borrowAmount) external virtual returns (uint);
    function borrowVerify(address vToken, address borrower, uint borrowAmount) external virtual;

    function repayBorrowAllowed(
        address vToken,
        address payer,
        address borrower,
        uint repayAmount) external virtual returns (uint);
    function repayBorrowVerify(
        address vToken,
        address payer,
        address borrower,
        uint repayAmount,
        uint borrowerIndex) external virtual;

    function liquidateBorrowAllowed(
        address vTokenBorrowed,
        address vTokenCollateral,
        address liquidator,
        address borrower,
        uint repayAmount) external virtual returns (uint);
    function liquidateBorrowVerify(
        address vTokenBorrowed,
        address vTokenCollateral,
        address liquidator,
        address borrower,
        uint repayAmount,
        uint seizeTokens) external virtual;

    function seizeAllowed(
        address vTokenCollateral,
        address vTokenBorrowed,
        address liquidator,
        address borrower,
        uint seizeTokens) external virtual returns (uint);
    function seizeVerify(
        address vTokenCollateral,
        address vTokenBorrowed,
        address liquidator,
        address borrower,
        uint seizeTokens) external virtual;

    function transferAllowed(address vToken, address src, address dst, uint transferTokens) external virtual returns (uint);
    function transferVerify(address vToken, address src, address dst, uint transferTokens) external virtual;

    /*** Liquidity/Liquidation Calculations ***/

    function liquidateCalculateSeizeTokens(
        address vTokenBorrowed,
        address vTokenCollateral,
        uint repayAmount) external virtual view returns (uint, uint);

    function mintedVAIOf(address owner) external virtual view returns (uint);
    function setMintedVAIOf(address owner, uint amount) external virtual returns (uint);
    function getVAIMintRate() external virtual view returns (uint);
}

